import csv
import json
import re


def normalize(name):
    # Collapse every run of whitespace to a single space, trim edges, then casefold.
    collapsed = re.sub(r"\s+", " ", name).strip()
    return collapsed.casefold()


def main():
    path = sys.argv[1]
    # Read faithfully as UTF-8 so input bytes are preserved round-trip.
    with open(path, "r", encoding="utf-8", newline="") as f:
        reader = csv.DictReader(f)
        totals = {}
        for row in reader:
            raw = row.get("item")
            if raw is None:
                continue
            norm = normalize(raw)
            if not norm:
                # Skip empty normalized names.
                continue
            qraw = row.get("quantity")
            if qraw is None:
                qraw = ""
            qraw = qraw.strip()
            if qraw == "":
                qty = 1  # Blank quantity means 1.
            else:
                qty = int(qraw)  # Nonnegative base-10 integer.
            totals[norm] = totals.get(norm, 0) + qty

    items = [{"item": k, "quantity": totals[k]} for k in sorted(totals)]
    out = sys.stdout
    try:
        out.reconfigure(encoding="utf-8")
    except (AttributeError, ValueError):
        pass
    json.dump(items, out, ensure_ascii=False)
    out.write("\n")


if __name__ == "__main__":
    main()"}

